interface I18nContextValue {
  lang: Language;
  setLang: (lang: Language) => void;
  isRtl: boolean;
  t: (key: string, vars?: Record<string, string | number>) => string;
  pageHeader: (page: PageId) => [string, string];
  roleLabel: (role: Role) => string;
  tripStatusLabel: (status: TripStatus | string) => string;
  proposalStatusLabel: (status: string) => string;
  licenseStatusLabel: (status: B2BLicense['status']) => string;
  requestStatusLabel: (status: B2BDeploymentRequest['status']) => string;
  entityStatusLabel: (status: string) => string;
  payrollStatusLabel: (status: string) => string;
  invoiceStatusText: (rawStatus: string) => string;
  alertSeverityLabel: (severity: string) => string;
  packText: (pack: B2BPackCatalogItem) => { name: string; audience: string; deliverables: string[] };
  packNameById: (packId: B2BPackId, fallbackName?: string) => string;
  checklistLabel: (id: string, fallback: string) => string;
}

const I18nContext = createContext<I18nContextValue | null>(null);

function detectInitialLanguage(): Language {
  if (typeof window === 'undefined') return 'fr';
  const params = new URLSearchParams(window.location.search);
  const q = params.get('lang')?.toLowerCase();
  if (q === 'fr' || q === 'en' || q === 'es' || q === 'ar') return q;
  const saved = window.localStorage.getItem(STORAGE_KEY)?.toLowerCase();
  if (saved === 'fr' || saved === 'en' || saved === 'es' || saved === 'ar') return saved;
  return 'fr';
}

export function I18nProvider({ children }: { children: React.ReactNode }) {
  const [lang, setLangState] = useState<Language>(detectInitialLanguage);

  useEffect(() => {
    if (typeof window !== 'undefined') {
      window.localStorage.setItem(STORAGE_KEY, lang);
      document.documentElement.lang = lang;
      document.documentElement.dir = lang === 'ar' ? 'rtl' : 'ltr';
    }
  }, [lang]);

  const value = useMemo<I18nContextValue>(() => {
    const dict = TRANSLATIONS[lang];
    const fallback = TRANSLATIONS.fr;

    const t = (key: string, vars?: Record<string, string | number>): string => {
      let raw = dict[key] ?? fallback[key] ?? key;
      if (vars) {
        for (const [k, v] of Object.entries(vars)) {
          raw = raw.replaceAll(`{${k}}`, String(v));
        }
      }
      return raw;
    };

    return {
      lang,
      setLang: setLangState,
      isRtl: lang === 'ar',
      t,
      pageHeader: (page) => [t(`page.${page}.title`), t(`page.${page}.sub`)],
      roleLabel: (role) => t(`role.${role}`),
      tripStatusLabel: (status) => dict[`trip.status.${status}`] ?? status,
      proposalStatusLabel: (status) => dict[`proposal.status.${status}`] ?? status,
      licenseStatusLabel: (status) => dict[`lic.status.${status}`] ?? status,
      requestStatusLabel: (status) => dict[`req.status.${status}`] ?? status,
      entityStatusLabel: (status) => dict[`entity.status.${status}`] ?? status,
      payrollStatusLabel: (status) => dict[`pay.status.${status}`] ?? status,
      invoiceStatusText: (rawStatus) => dict[`inv.status.${rawStatus}`] ?? rawStatus,
      alertSeverityLabel: (severity) => dict[`alert.sev.${severity}`] ?? severity,
      packText: (pack) => {
        if (pack.customized || !PACK_I18N[lang][pack.id]) {
          return {
            name: pack.name,
            audience: pack.audience,
            deliverables: pack.deliverables,
          };
        }
        return PACK_I18N[lang][pack.id];
      },
      packNameById: (packId, fallbackName) => {
        const defaultFrName = PACK_I18N.fr[packId]?.name;
        if (fallbackName && (!defaultFrName || fallbackName !== defaultFrName)) {
          return fallbackName;
        }
        return PACK_I18N[lang][packId]?.name || fallbackName || packId;
      },
      checklistLabel: (id, fallbackLabel) =>
        CHECKLIST_LABELS[lang][id] || fallbackLabel,
    };
  }, [lang]);

  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>;
}

export function useI18n(): I18nContextValue {
  const ctx = useContext(I18nContext);
  if (!ctx) {
    throw new Error('useI18n must be used inside I18nProvider');
  }
  return ctx;
}

export function LanguageSwitcher({ variant = 'dark' }: { variant?: 'dark' | 'light' }) {
  const { lang, setLang } = useI18n();
  return (
    <div
      className={`inline-flex items-center p-0.5 rounded-lg shrink-0 ${
        variant === 'dark' ? 'bg-white/10' : 'bg-slate-100 border border-slate-200'
      }`}
      role="group"
      aria-label="Language"
    >
      {LANGUAGE_OPTIONS.map((opt) => {
        const active = lang === opt.code;
        return (
          <button
            key={opt.code}
            type="button"
            title={opt.label}
            onClick={() => setLang(opt.code)}
            className={`px-2 py-1 rounded-md text-[11px] font-bold transition-colors whitespace-nowrap shrink-0 ${
              active
                ? variant === 'dark'
                  ? 'bg-white text-[#17324d]'
                  : 'bg-[#17324d] text-white'
                : variant === 'dark'
                  ? 'text-slate-200 hover:text-white'
                  : 'text-slate-600 hover:text-[#17324d]'
            }`}
          >
            {opt.short}
          </button>
        );
      })}
    </div>
  );
}
